local date = require("Frame.date")

---@class WorldBossUtils
local WorldBossUtils = {}

function WorldBossUtils.GetDurationTime(startDay, endDay)
    if not startDay or not endDay then
        return 0
    end

    local timeSpan = date.diff(endDay, startDay)
    if not timeSpan then
        return 0
    end
    return timeSpan:spanseconds()
end

---@return WorldBossPlanVo
function WorldBossUtils.GetWorldBossPlanVoById(scheduleId)
