    if not curWorldBossVo then end

    local curBossCardSkin = CfUtils.GetCfVo(AutoIds.IdSetting113, "CardSkinVo", curWorldBossVo.skinId)
    if not curBossCardSkin then return end

    return checkString(curBossCardSkin.name)
end

return WorldBossUtils